<template><VueFlow v-model:nodes="s.nodes" v-model:edges="s.edges" :node-types="types" @connect="connect" @node-click="pick"><Background/><Controls/><MiniMap/></VueFlow></template><script setup lang="ts">import {VueFlow,Background,Controls,MiniMap} from '@vue-flow/core';import '@vue-flow/core/dist/style.css';import '@vue-flow/core/dist/theme-default.css';import {useWorkflowStore}from '../../stores/workflow';import StartNode from './nodes/StartNode.vue';import LLMNode from './nodes/LLMNode.vue';import ToolNode from './nodes/ToolNode.vue';import ConditionNode from './nodes/ConditionNode.vue';import CodeNode from './nodes/CodeNode.vue';import KnowledgeNode from './nodes/KnowledgeNode.vue';import JoinNode from './nodes/JoinNode.vue';import EndNode from './nodes/EndNode.vue';const s=useWorkflowStore();const types={start:StartNode,llm:LLMNode,tool:ToolNode,condition:ConditionNode,code:CodeNode,knowledge:KnowledgeNode,join:JoinNode,end:EndNode};const connect=(x:any)=>s.connectNodes({id:crypto.randomUUID(),source:x.source,target:x.target});const pick=({node}:any)=>s.selectedNode=node</script>
